-- R54 (#59): before sign-up opens, a second owner reads every owned table and view as memory_tenant and sees 0 rows.
-- Read only, and rolled back. Run: supabase db query --linked -f memory/e2e/isolation_check.sql (rows_seen must be 0). The
-- same file with memory.owner set to Wen's id is the positive control (rows_seen > 0).
begin read only;
set local role memory_tenant;
select set_config('memory.owner', gen_random_uuid()::text, true);
select sum(n) as rows_seen, count(*) as relations, json_agg(t) filter (where n > 0) as leaking from (select 'account' as t, count(*) as n from memory.account union all select 'admin_audit' as t, count(*) as n from memory.admin_audit union all select 'agent' as t, count(*) as n from memory.agent union all select 'agent_binding' as t, count(*) as n from memory.agent_binding union all select 'blob' as t, count(*) as n from memory.blob union all select 'board_seen' as t, count(*) as n from memory.board_seen union all select 'burst' as t, count(*) as n from memory.burst union all select 'co_use' as t, count(*) as n from memory.co_use union all select 'confidence_log' as t, count(*) as n from memory.confidence_log union all select 'device' as t, count(*) as n from memory.device union all select 'entitlement' as t, count(*) as n from memory.entitlement union all select 'entry' as t, count(*) as n from memory.entry union all select 'entry_blob' as t, count(*) as n from memory.entry_blob union all select 'entry_embedding' as t, count(*) as n from memory.entry_embedding union all select 'entry_provenance' as t, count(*) as n from memory.entry_provenance union all select 'event' as t, count(*) as n from memory.event union all select 'feedback' as t, count(*) as n from memory.feedback union all select 'judge_cache' as t, count(*) as n from memory.judge_cache union all select 'link' as t, count(*) as n from memory.link union all select 'mcp_client' as t, count(*) as n from memory.mcp_client union all select 'mcp_session' as t, count(*) as n from memory.mcp_session union all select 'message' as t, count(*) as n from memory.message union all select 'message_delivery' as t, count(*) as n from memory.message_delivery union all select 'quest' as t, count(*) as n from memory.quest union all select 'quest_blob' as t, count(*) as n from memory.quest_blob union all select 'quest_note' as t, count(*) as n from memory.quest_note union all select 'retrieval' as t, count(*) as n from memory.retrieval union all select 'shadow_retrieval' as t, count(*) as n from memory.shadow_retrieval union all select 'source' as t, count(*) as n from memory.source union all select 'upload' as t, count(*) as n from memory.upload union all select 'usage' as t, count(*) as n from memory.usage union all select 'entry_current' as t, count(*) as n from memory.entry_current union all select 'unanswered_recall' as t, count(*) as n from memory.unanswered_recall union all select 'entries_overview' as t, count(*) as n from memory.entries_overview union all select 'links_readable' as t, count(*) as n from memory.links_readable union all select 'recalls_recent' as t, count(*) as n from memory.recalls_recent union all select 'events_recent' as t, count(*) as n from memory.events_recent) s;
rollback;
